import numpy as np
L=open('answer.xyz').read().split('\n'); n=int(L[0]); print("atoms",n)
sym=[l.split()[0] for l in L[2:2+n]]; X=np.array([list(map(float,l.split()[1:4])) for l in L[2:2+n]])
from collections import Counter; print(Counter(sym))
D=np.linalg.norm(X[:,None]-X[None],axis=-1); np.fill_diagonal(D,9)
print("min dist",D.min().round(2))
# check all bonds for heavy-atom sanity: count neighbors for each C,N,O
cov={'H':0.31,'C':0.76,'N':0.71,'O':0.66,'F':0.57,'Cl':1.02,'Ge':1.20,'Au':1.36}
bad=[]
for i,s in enumerate(sym):
    nb=[j for j in range(n) if D[i,j]<1.25*(cov[s]+cov[sym[j]])]
    if s=='C' and len(nb) not in (3,4): bad.append((i,s,len(nb)))
    if s=='H' and len(nb)!=1: bad.append((i,s,len(nb)))
print("bad valences",bad)
